head.script:
scwin.trigger01_onclick = function(e) {
    var winID = "sample01"
    var url = "./windowContainer_setWindowPosition_WPF-1726_(WSQ-2854_)_sub.xml";
    mdi.createWindow(winID, null, url, winID);
};
scwin.trigger4_onclick = function(e) {
    mdi.setWindowSize(200, '300');
    mdi.setWindowPosition(30, '10px');
};
scwin.trigger5_onclick = function(e) {
    mdi.setWindowSize('200', 300);
    mdi.setWindowPosition('300px', 10);
};
scwin.getStyle = function(style) {
    var el = WebSquare.wUnit.getDomById($p.id + 'mdi_subWindow0');
    return el.style[style];
}
scwin.checktype = function() {
    return typeof mdi_subWindow0;
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 1. 샘플파일을 실행 후 page버튼을 클릭한다.
    //1. Run the sample file and click the page button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger01').click()");
    // verify step 1. sample01이라는 mdi화면이 보여진다.
    //1. The mdi screen named sample01 is displayed.
    WebSquare.wUnit.addCommand("assert", "scwin.checktype()", "object");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('mdi_subWindow0_header_title').innerText", "sample01");
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 2. size(px)버튼을 클릭한다.
    //2. Click the size (px) button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger4').click()");
    // verify step 2. size와 position에서 설정한 값대로 보여진다.
    //2. It is displayed as the value set in size and position.
    WebSquare.wUnit.addCommand("assert", "scwin.getStyle('top')", "10px");
    WebSquare.wUnit.addCommand("assert", "scwin.getStyle('left')", "30px");
    WebSquare.wUnit.addCommand("assert", "scwin.getStyle('width')", "200px");
    WebSquare.wUnit.addCommand("assert", "scwin.getStyle('height')", "300px");
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 3. size(number)버튼을 클릭한다.
    //3. Click the size (number) button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger5').click()");
    // verify step 3. size와 position에서 설정한 값대로 보여진다.
    //3. It is displayed as the value set in size and position.
    WebSquare.wUnit.addCommand("assert", "scwin.getStyle('top')", "10px");
    WebSquare.wUnit.addCommand("assert", "scwin.getStyle('left')", "300px");
    WebSquare.wUnit.addCommand("assert", "scwin.getStyle('width')", "200px");
    WebSquare.wUnit.addCommand("assert", "scwin.getStyle('height')", "300px");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Created By: Sang.do
    //Created By: 25-Jan-2018
    //end unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
